public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int n = sc.nextInt();
    Map<Integer, Integer> map = new HashMap<>();

    for(int i = 0; i < n; i++){
        int deliciousness = sc.nextInt();
        int color = sc.nextInt();

        if(map.containsKey(color)){
            int minDeliciousness = map.get(color);

            if(minDeliciousness > deliciousness){
                map.put(color, deliciousness);
            }
        } else {
            map.put(color, deliciousness);
        }
    }

    Integer maxMinDeliciousness = 0;

    for(Integer value : map.values()){
        if(maxMinDeliciousness < value){
            maxMinDeliciousness = value;
        }
    }
    System.out.println(maxMinDeliciousness);
}
